        c = new Cooler();
    }

    function _run(uint256 amount_, uint256 interest_, uint256 loanToCollateral_, uint256 duration_, bool repayDirect_, bool isCallback_) internal {
        vm.assume(loanToCollateral_ > 0);
        vm.assume(duration_ > 0);
        vm.assume(amount_ <= 1e30);
        vm.assume(interest_ <= 1e18);
        try c.requestLoan(amount_, interest_, loanToCollateral_, duration_) {} catch { return; }
        bool reverted;
        uint256 returnedLoanID;
        try c.clearRequest(0, repayDirect_, isCallback_) returns (uint256 id) {
            returnedLoanID = id;
            reverted = false;
        } catch {
            reverted = true;
        }
